import { Component, createContext, createRef, useContext, useEffect } from 'react';
import { esErrorLazy } from '../apps/plataforma/lazyRoute.js';
import { esAmaDelDocument } from '../apps/plataforma/interruptors.js';

const RecoveryContext = createContext(null);

/** Testimoni explícit dins del contingut de Suspense, mai en el seu fallback.
 * Confirma l'episodi després dels efectes descendents, sense afegir DOM ni
 * remuntar la vista. El token i la neteja invaliden errors i testimonis antics.
 * Sense testimoni, sols resetKey renova el pressupost; un fallback no és salut.
 */
export function RouteRecoveryReady({ children }) {
  const owner = useContext(RecoveryContext);
  useEffect(() => {
    if (!owner) return;
    let activa = true;
    const token = owner.inicia();
    queueMicrotask(() => { if (activa) owner.confirma(token); });
    return () => { activa = false; };
  }, [owner]);
  return children;
}

/** Política única de recuperació. Cada error lazy té un sol propietari: la
 * instància més pròxima, de ruta o de peça. onlyLazy retorna els errors de
 * domini al seu Slot existent; cap propietari reintenta imports automàticament.
 */
export class RouteErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { error: null, resetKey: props.resetKey, reintents: 0 };
    this.episodi = 0;
    this.recuperacio = { inicia: this.iniciaConfirmacio, confirma: this.confirmaVista, resetKey: props.resetKey };
    this.titolRef = createRef();
    this.reintentRef = createRef();
  }
  static getDerivedStateFromError(error) { return { error }; }
  static getDerivedStateFromProps(props, state) {
    return props.resetKey !== state.resetKey
      ? { error: null, resetKey: props.resetKey, reintents: 0 }
      : null;
  }
  componentDidCatch(error, info) {
    this.episodi += 1;
    console.error('[RouteErrorBoundary] Error capturat a la ruta:', error, info);
    if (document.activeElement === document.body) this.titolRef.current?.focus();
  }
  componentWillUnmount() { this.episodi += 1; }
  iniciaConfirmacio = () => this.episodi;
  confirmaVista = (token) => {
    if (token === this.episodi && !this.state.error && this.state.reintents)
      this.setState({ reintents: 0 });
  };
  getSnapshotBeforeUpdate() {
    return this.reintentRef.current === document.activeElement;
  }
  componentDidUpdate(_propsAnteriors, estatAnterior, controlTeniaFocus) {
    if (_propsAnteriors.resetKey !== this.props.resetKey) this.episodi += 1;
    if (!this.state.error) return;
    // Un reintent pot remuntar el panell; desactivar o llevar el control
    // també pot deixar el focus al body. Conservem el focus dins del problema
    // sense prendre'l d'un control de navegació exterior.
    if (estatAnterior.reintents !== this.state.reintents
      || (controlTeniaFocus && (!this.reintentRef.current || this.reintentRef.current.disabled))) {
      this.titolRef.current?.focus();
    }
  }
  recarrega = () => {
    // Revalida el clic: l’amfitrió d’una incrustació i un equip fora de línia
    // no donen autoritat al mòdul per a recarregar el document.
    if (!esAmaDelDocument(this.props.externalConfig) || navigator.onLine === false) return;
    window.location.reload();
  };
  render() {
    const { error, reintents } = this.state;
    if (!error) {
      if (this.recuperacio.resetKey !== this.props.resetKey) this.recuperacio = { ...this.recuperacio, resetKey: this.props.resetKey };
      return <RecoveryContext.Provider value={this.recuperacio}>{this.props.children}</RecoveryContext.Provider>;
    }
    const importFallat = esErrorLazy(error);
    if (this.props.onlyLazy && !importFallat) throw error;
    const ama = esAmaDelDocument(this.props.externalConfig);
    const enLinia = this.props.enLinia ?? (typeof navigator === 'undefined' || navigator.onLine !== false);
    const detall = this.props.mostraDetall ?? Boolean(import.meta.env.DEV);
    return (
      <div className="sdp-route-error" role="alert">
        <h2 className="sdp-route-error__titol" tabIndex={-1} ref={this.titolRef}>Hi ha hagut un problema</h2>
        <p>Aquesta secció no ha pogut carregar-se correctament.</p>
        {detall ? <pre className="sdp-error-pre">{error.cause?.message || error.message || String(error)}</pre> : null}
        {importFallat ? (
          <>
            {ama ? <p>Recarregar reinicia l’aplicació i descarta les dades que només viuen a la memòria. Desa o exporta el que necessites abans.</p> : null}
            {!ama ? <p>Torna a obrir el mòdul des de la pàgina que l’allotja.</p> : null}
            {!enLinia ? <p>Recupera la connexió abans de tornar a carregar.</p> : null}
            {ama ? <button ref={this.reintentRef} type="button" className="sdp-boto sdp-boto--secundari sdp-route-error__reintent"
              disabled={!enLinia} onClick={this.recarrega}>Recarrega l’aplicació</button> : null}
          </>
        ) : (
          <>
            {reintents ? <p>La vista continua fallant. Pots obrir una altra secció amb el menú.</p> : null}
            <button ref={this.reintentRef} type="button" className="sdp-boto sdp-boto--secundari sdp-route-error__reintent"
              disabled={reintents >= 1} onClick={() => this.setState({ error: null, reintents: reintents + 1 })}>Intentar de nou</button>
          </>
        )}
      </div>
    );
  }
}

import { StrictMode, Suspense, useEffect } from 'react';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { RouteErrorBoundary, RouteRecoveryReady } from './RouteErrorBoundary.jsx';
import { lazyRoute } from '../apps/plataforma/lazyRoute.js';
import { SlotErrorBoundary } from '../components/universal/workspace/SlotErrorBoundary.jsx';

beforeEach(() => { vi.spyOn(console, 'error').mockImplementation(() => {}); });
afterEach(() => { vi.unstubAllGlobals(); cleanup(); vi.restoreAllMocks(); });
const domWindow = window;
const config = { manageDocumentHead: true };
const unavailable = () => { throw new TypeError('Failed to fetch dynamically imported module'); };
const view = (Child, props = {}) => <RouteErrorBoundary resetKey="/disseny" externalConfig={config} mostraDetall={false} {...props}>
  <Suspense fallback={<p>Carregant…</p>}><SlotErrorBoundary><Child /></SlotErrorBoundary></Suspense>
</RouteErrorBoundary>;
const reloadWindow = () => {
  const reload = vi.fn();
  const host = { location: { reload }, self: domWindow, top: domWindow };
  // Keep the actual DOM constructors and event target used by React.
  vi.stubGlobal('window', new Proxy(domWindow, {
    get(target, key) {
      if (Object.hasOwn(host, key)) return host[key];
      const value = Reflect.get(target, key, target);
      return ['addEventListener', 'removeEventListener', 'dispatchEvent'].includes(key)
        ? value.bind(target) : value;
    },
  }));
  return { host, reload };
};

test('un import fallat profund arriba a l’únic propietari i no recarrega ni reintenta automàticament', async () => {
  const importa = vi.fn(unavailable), Child = lazyRoute(importa);
  render(view(Child));
  await screen.findByRole('alert');
  expect(importa).toHaveBeenCalledTimes(1);
  expect(screen.queryByText('Reintenta')).toBeNull();
  expect(screen.queryByText('Intentar de nou')).toBeNull();
  expect(screen.queryByText('Failed to fetch dynamically imported module')).toBeNull();
  expect(screen.getByText(/descarta les dades que només viuen a la memòria/)).toBeTruthy();
  const { reload } = reloadWindow();
  expect(reload).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Recarrega l’aplicació' }));
  expect(reload).toHaveBeenCalledTimes(1);
});

test.each([false, undefined])('un document alié amb manageDocumentHead=%s no oferix recàrrega operativa', async (manageDocumentHead) => {
  render(view(lazyRoute(unavailable), { externalConfig: { manageDocumentHead } }));
  await screen.findByRole('alert');
  expect(screen.queryByRole('button', { name: 'Recarrega l’aplicació' })).toBeNull();
  expect(screen.getByText(/pàgina que l’allotja/)).toBeTruthy();
  expect(screen.queryByText(/Recarregar reinicia l’aplicació/)).toBeNull();
});

test.each(['embedded', 'iframe', 'offline'])('revalida %s en el clic encara que la vista s’haguera pintat habilitada', async (mode) => {
  render(view(lazyRoute(unavailable)));
  await screen.findByRole('alert');
  const boto = screen.getByRole('button', { name: 'Recarrega l’aplicació' });
  expect(boto.disabled).toBe(false);
  const { host, reload } = reloadWindow();
  if (mode === 'embedded') host.__SDP_EMBEDDED__ = true;
  if (mode === 'iframe') host.top = {};
  if (mode === 'offline') vi.stubGlobal('navigator', { onLine: false });
  fireEvent.click(boto);
  expect(reload).not.toHaveBeenCalled();
});

test('fora de línia ho diu i tornar a estar en línia habilita el clic explícit', async () => {
  const Child = lazyRoute(unavailable);
  const vista = render(view(Child, { enLinia: false }));
  await screen.findByRole('alert');
  expect(screen.getByRole('button', { name: 'Recarrega l’aplicació' }).disabled).toBe(true);
  expect(screen.getByText(/Recupera la connexió/)).toBeTruthy();
  vista.rerender(view(Child, { enLinia: true }));
  expect(screen.getByRole('button', { name: 'Recarrega l’aplicació' }).disabled).toBe(false);
});

test('el reintent d’un render transitori funciona; el mateix render persistent queda acotat', () => {
  let falla = true;
  function Vista() { if (falla) throw Error('render'); return <p>Vista recuperada</p>; }
  // A render failure belongs to the route here (slots retain their own domain recovery).
  const tree = (key = '/a') => <RouteErrorBoundary resetKey={key}><Vista /></RouteErrorBoundary>;
  const vista = render(tree());
  fireEvent.click(screen.getByRole('button', { name: 'Intentar de nou' }));
  expect(screen.getByRole('button', { name: 'Intentar de nou' }).disabled).toBe(true);
  falla = false; vista.rerender(tree('/b'));
  expect(screen.getByText('Vista recuperada')).toBeTruthy();
  falla = true; vista.rerender(tree('/c')); falla = false;
  fireEvent.click(screen.getByRole('button', { name: 'Intentar de nou' }));
  expect(screen.getByText('Vista recuperada')).toBeTruthy();
});

test('canviar de ruta conserva el rebuig lazy de React: cap falso reintent del mateix import', async () => {
  const importa = vi.fn(() => Promise.reject(Error('chunk absent'))), Child = lazyRoute(importa);
  const vista = render(view(Child));
  await screen.findByRole('alert');
  vista.rerender(view(Child, { resetKey: '/altre' }));
  await screen.findByRole('alert');
  expect(importa).toHaveBeenCalledTimes(1);
});

test('un segon render fallat conserva el focus al títol del problema', () => {
  const mateixError = new Error('render persistent');
  function Trencada() { throw mateixError; }
  render(<RouteErrorBoundary resetKey="/a" mostraDetall={false}><Trencada /></RouteErrorBoundary>);
  const boto = screen.getByRole('button', { name: 'Intentar de nou' });
  boto.focus();
  fireEvent.click(boto);
  expect(screen.getByRole('button', { name: 'Intentar de nou' }).disabled).toBe(true);
  expect(document.activeElement).toBe(screen.getByRole('heading', { level: 2, name: 'Hi ha hagut un problema' }));
});

test('passar fora de línia amb focus a recarregar enfoca el problema i conserva el control desactivat', async () => {
  const Child = lazyRoute(unavailable);
  const vista = render(view(Child, { enLinia: true }));
  await screen.findByRole('alert');
  screen.getByRole('button', { name: 'Recarrega l’aplicació' }).focus();
  vista.rerender(view(Child, { enLinia: false }));
  expect(screen.getByRole('button', { name: 'Recarrega l’aplicació' }).disabled).toBe(true);
  expect(document.activeElement).toBe(screen.getByRole('heading', { level: 2 }));
});

test('perdre autoritat amb focus a recarregar no deixa el focus al body', async () => {
  const Child = lazyRoute(unavailable);
  const vista = render(view(Child));
  await screen.findByRole('alert');
  screen.getByRole('button', { name: 'Recarrega l’aplicació' }).focus();
  vista.rerender(view(Child, { externalConfig: { manageDocumentHead: false } }));
  expect(screen.queryByRole('button', { name: 'Recarrega l’aplicació' })).toBeNull();
  expect(document.activeElement).toBe(screen.getByRole('heading', { level: 2 }));
});

test('un canvi de connexió no pren el focus d’un control fora del panell', async () => {
  const Child = lazyRoute(unavailable);
  const tree = (enLinia) => <><button type="button">Menú exterior</button>{view(Child, { enLinia })}</>;
  const vista = render(tree(true));
  await screen.findByRole('alert');
  const exterior = screen.getByRole('button', { name: 'Menú exterior' });
  exterior.focus();
  vista.rerender(tree(false));
  expect(document.activeElement).toBe(exterior);
});


test('onlyLazy retorna un error de domini al Slot existent, sense panell lazy ni recàrrega', () => {
 function Trencada() { throw new Error('domini sintètic'); }
 render(<SlotErrorBoundary domini="detall"><RouteErrorBoundary onlyLazy resetKey="a" externalConfig={config}><Trencada /></RouteErrorBoundary></SlotErrorBoundary>);
 expect(screen.getByRole('heading', { name: /El detall s'ha esfondrat/ })).toBeTruthy();
 expect(screen.queryByRole('heading', { name: 'Hi ha hagut un problema' })).toBeNull();
 expect(screen.queryByRole('button', { name: 'Recarrega l’aplicació' })).toBeNull();
});
test('el propietari lazy més pròxim conserva les peces exteriors i no duplica la recuperació', async () => {
 const importa=vi.fn(unavailable),Child=lazyRoute(importa);
 render(<RouteErrorBoundary resetKey="ruta" externalConfig={config}><p>Llista exterior viva</p><SlotErrorBoundary domini="detall"><RouteErrorBoundary onlyLazy resetKey="item-a" externalConfig={config}><Suspense fallback={<p>Carregant detall</p>}><Child /></Suspense></RouteErrorBoundary></SlotErrorBoundary></RouteErrorBoundary>);
 await screen.findByRole('alert');
 expect(screen.getByText('Llista exterior viva')).toBeTruthy();
 expect(screen.getAllByRole('button',{name:'Recarrega l’aplicació'})).toHaveLength(1);
 expect(importa).toHaveBeenCalledTimes(1);
});
test('un reintent sa confirmat renova el pressupost per a una fallada posterior de la mateixa ruta', async () => {
 let falla=true,muntatges=0;
 function Vista(){useEffect(()=>{muntatges++;},[]);if(falla)throw new Error('fallada sintètica');return <p>Vista recuperada</p>;}
 const tree=()=> <RouteErrorBoundary resetKey="mateixa-ruta" mostraDetall={false}><RouteRecoveryReady><Vista /></RouteRecoveryReady></RouteErrorBoundary>;
 const vista=render(tree());
 falla=false;fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
 await act(async()=>{await Promise.resolve();});
 expect(screen.getByText('Vista recuperada')).toBeTruthy();
 expect(muntatges).toBe(1,'confirmar salut no remunta la vista recuperada');
 falla=true;vista.rerender(tree());
 expect(screen.getByRole('button',{name:'Intentar de nou'}).disabled).toBe(false);
 fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
 expect(screen.getByRole('button',{name:'Intentar de nou'}).disabled).toBe(true);
});
for(const estricte of [false,true])test(`una fallada d’efecte amb Error nou a cada mount no renova intents (StrictMode=${estricte})`,async()=>{
 let efectes=0;
 function Trencada(){useEffect(()=>{efectes++;throw new Error('efecte nou '+efectes);},[]);return <p>Contingut abans de l’efecte</p>;}
 const frontera=<RouteErrorBoundary resetKey="mateixa-ruta" mostraDetall={false}><RouteRecoveryReady><Trencada /></RouteRecoveryReady></RouteErrorBoundary>;
 render(estricte?<StrictMode>{frontera}</StrictMode>:frontera);
 await act(async()=>{await Promise.resolve();});
 const abans=efectes;fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
 await act(async()=>{await Promise.resolve();});
 expect(efectes).toBeGreaterThan(abans);
 expect(screen.getByRole('button',{name:'Intentar de nou'}).disabled).toBe(true);
 expect(screen.queryByText('Contingut abans de l’efecte')).toBeNull();
});


test('una confirmació sana pendent no renova el pressupost si la vista ja ha tornat a fallar',()=>{
 const microtasks=[];vi.stubGlobal('queueMicrotask',callback=>microtasks.push(callback));
 let falla=true;
 function Vista(){if(falla)throw new Error('episodi no confirmat');return <p>Moment sa</p>;}
 const tree=()=> <RouteErrorBoundary resetKey="mateixa-ruta" mostraDetall={false}><RouteRecoveryReady><Vista /></RouteRecoveryReady></RouteErrorBoundary>;
 const vista=render(tree());
 falla=false;fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
