 let espera=false,efectes=0,resol;
 const promesa=new Promise(resolve=>{resol=resolve;});
 function Vista(){
  if(espera)throw promesa;
  useEffect(()=>{efectes++;throw new Error('efecte del mateix episodi '+efectes);},[]);
  return <p>Vista abans de l’efecte</p>;
 }
