 render(estricte?<StrictMode>{frontera}</StrictMode>:frontera);
 await act(async()=>{await Promise.resolve();});
 const abans=efectes;espera=true;fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
 await act(async()=>{await Promise.resolve();});
 expect(screen.getByText('Esperant vista')).toBeTruthy();
 espera=false;await act(async()=>{resol();await promesa;});
