 const microtasks=[];vi.stubGlobal('queueMicrotask',callback=>microtasks.push(callback));
 let falla=true,ready=true;
 function Vista(){if(falla)throw new Error('testimoni retirat');return <p>Vista temporal</p>;}
 const tree=()=> <RouteErrorBoundary resetKey="mateixa-ruta" mostraDetall={false}>{ready?<RouteRecoveryReady><Vista /></RouteRecoveryReady>:<Vista />}</RouteErrorBoundary>;
 const vista=render(tree());falla=false;fireEvent.click(screen.getByRole('button',{name:'Intentar de nou'}));
 expect(screen.getByText('Vista temporal')).toBeTruthy();
 ready=false;vista.rerender(tree());
 act(()=>{while(microtasks.length)microtasks.shift()();});
