const MobileNav = memo(function MobileNav() {
  const { language } = useUIState();
  const { t } = useUIActions();
  const navigate = useNavigate();
  const [telefonadesObertes, setTelefonadesObertes] = useState(false);
  const telefonades = t('section.xat.rail.telefonades', 'Telefonades');

  const enllacMobil = (section) => {
    const Icon = section.icon;
    const labels = section.kind === 'gestoria'
      ? { label: section.label, shortLabel: section.shortLabel }
      : getSectionLabels(section.id, language);
    return (
      <NavLink key={section.id} to={section.path} matchPaths={section.subrutes} className="nav-item" aria-label={labels.label}>
        <Icon className="nav-item__icon" strokeWidth={2.1} aria-hidden="true" focusable="false" />
        <span className="nav-item__text">
          <strong>{labels.shortLabel}</strong>
        </span>
      </NavLink>
    );
  };

  const vesAlPanell = () => {
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (document.startViewTransition && !prefersReducedMotion) {
      const transicio = document.startViewTransition(() => navigate('/control'));
      transicio?.ready?.catch(() => {});
    } else {
      navigate('/control');
    }
  };


  return (
    <>
      <nav className="mobile-nav" aria-label="Navegació mòbil">
        {MOBILE_NAV_LEADING.map((section) => enllacMobil(section))}
        <button type="button" className="mobile-nav__cta" onClick={vesAlPanell} aria-label={t('nav.panel', 'Panell de Control')}>
          <Settings strokeWidth={2.1} />
        </button>
        {MOBILE_NAV_TRAILING.map((section) => enllacMobil(section))}
        <button type="button" className="nav-item" aria-label={telefonades} aria-haspopup="dialog"
          onClick={(event) => { event.currentTarget.focus(); setTelefonadesObertes(true); }}>
          <Phone className="nav-item__icon" strokeWidth={2.1} aria-hidden="true" focusable="false" />
          <span className="nav-item__text"><strong>{telefonades}</strong></span>
        </button>
      </nav>
      <Dialeg obert={telefonadesObertes} onTanca={() => setTelefonadesObertes(false)} titol={telefonades}
        accions={<button type="button" className="sdp-boto" onClick={() => setTelefonadesObertes(false)}>{t('common.entesos', 'Entesos')}</button>}>
        <p>{t('nav.telefonades.avis', 'Aquest és un projecte lliure CC. Aquesta funció està prevista per a quan puguem mantenir-la econòmicament.')}</p>
      </Dialeg>
    </>
  );
});

/**
 * Plataforma d'Apps Enxufables · l'API pública per a les apps.
 *
 * Una app (src/apps/<id>/) només importa de la plataforma per ací. La resta
 * de fitxers de src/apps/plataforma/ són del nucli i poden canviar.
 *
 *   useApp()               · { manifest, base: '/app/<id>', ruta(...trams) }
 *   useInterruptorsApp()   · { avalua(id), actiu(id), apaga(id, apagat) }
 *   ClosaAplicacio         · l'esquelet comú de tres columnes (TPV, La Compra…):
 *                            una taula de rutes { path, params?, Esquerra?, Mig,
 *                            Detall, estret? } i les columnes ixen de la URL
 *   useClosaAplicacio()    · dins d'una columna: { mida, panellObert, obriPanell, tancaPanells }
 *   validaTaulaDeClosa     · la validació de la taula de ClosaAplicacio
 *   useParametresConsulta  · llig i escriu la consulta (push) amb validadors
 *   useRutaApp(rutes)      · la ruta interna que casa amb la URL, amb els paràmetres validats
 *   validaRutes, coincidixRuta, esSlug, esIdOpac, esData, esUuid, VALIDADORS
 *   ESDEVENIMENT_NAVEGA    · per a les apps externes (custom elements)
 *   ENTITAT_PROJECTE, autoriaDe(autor) · la boina d'autor de les targetes
 *                            d'una app ({ nom, poble, avatar, href }),
 *                            resolta per identificador (REGLA D'OR 1, 261004)
 */
export { useApp, useInterruptorsApp } from './PlataformaContext.jsx';
export { ClosaAplicacio, useClosaAplicacio, validaTaulaDeClosa } from './ClosaAplicacio.jsx';
export {
